import asyncio
import asyncssh
import yaml
from concurrent.futures import ThreadPoolExecutor
import logging
from typing import Dict, List, Any

class AnsibleLikeOrchestrator:
    def __init__(self, max_concurrent=50):
        self.max_concurrent = max_concurrent
        self.semaphore = asyncio.Semaphore(max_concurrent)
        self.results = {}
        self.failed_hosts = set()

    async def execute_playbook(self, inventory: Dict, playbook: List[Dict]):
        """Execute playbook across all hosts in inventory"""
        tasks = []

        for group_name, hosts in inventory.items():
            for host in hosts:
                task = asyncio.create_task(
                    self.execute_on_host(host, playbook, group_name)
                )
                tasks.append(task)

        # Execute all tasks concurrently
        results = await asyncio.gather(*tasks, return_exceptions=True)
        return self.compile_results(results)

    async def execute_on_host(self, host: Dict, playbook: List[Dict], group: str):
        """Execute playbook on a single host"""
        async with self.semaphore:  # Limit concurrent connections
            host_results = {
                'host': host['hostname'],
                'group': group,
                'tasks': [],
                'status': 'success',
                'start_time': asyncio.get_event_loop().time()
            }

            try:
                # Establish SSH connection
                async with asyncssh.connect(
                    host['hostname'],
                    username=host.get('username', 'root'),
                    password=host.get('password'),
                    private_key=host.get('private_key'),
                    connect_timeout=30
                ) as conn:

                    # Execute each task in the playbook
                    for task in playbook:
                        task_result = await self.execute_task(conn, task, host)
                        host_results['tasks'].append(task_result)

                        # Stop on failure if not ignored
                        if not task_result['success'] and not task.get('ignore_errors', False):
                            host_results['status'] = 'failed'
                            self.failed_hosts.add(host['hostname'])
                            break

            except Exception as e:
                host_results['status'] = 'unreachable'
                host_results['error'] = str(e)
                self.failed_hosts.add(host['hostname'])
                logging.error(f"Failed to connect to {host['hostname']}: {e}")

            host_results['end_time'] = asyncio.get_event_loop().time()
            host_results['duration'] = host_results['end_time'] - host_results['start_time']

            return host_results

    async def execute_task(self, conn, task: Dict, host: Dict) -> Dict:
        """Execute a single task on a host"""
        task_result = {
            'name': task.get('name', 'Unnamed task'),
            'module': task.get('module'),
            'success': False,
            'changed': False,
            'output': '',
            'start_time': asyncio.get_event_loop().time()
        }

        try:
            if task['module'] == 'command':
                result = await conn.run(task['args'], check=False)
                task_result['output'] = result.stdout
                task_result['stderr'] = result.stderr
                task_result['return_code'] = result.exit_status
                task_result['success'] = result.exit_status == 0
                task_result['changed'] = True  # Commands always considered changed

            elif task['module'] == 'copy':
                await self.copy_file(conn, task['args'])
                task_result['success'] = True
                task_result['changed'] = True

            elif task['module'] == 'service':
                await self.manage_service(conn, task['args'])
                task_result['success'] = True
                task_result['changed'] = True

            elif task['module'] == 'package':
                result = await self.manage_package(conn, task['args'])
                task_result.update(result)

        except Exception as e:
            task_result['error'] = str(e)
            logging.error(f"Task failed on {host['hostname']}: {e}")

        task_result['end_time'] = asyncio.get_event_loop().time()
        task_result['duration'] = task_result['end_time'] - task_result['start_time']

        return task_result

    async def copy_file(self, conn, args: Dict):
        """Copy file to remote host"""
        src = args['src']
        dest = args['dest']

        # Create directory if needed
        await conn.run(f"mkdir -p {'/'.join(dest.split('/')[:-1])}")

        # Copy file
        async with conn.start_sftp_client() as sftp:
            await sftp.put(src, dest)

        # Set permissions if specified
        if 'mode' in args:
            await conn.run(f"chmod {args['mode']} {dest}")

    async def manage_service(self, conn, args: Dict):
        """Manage system services"""
        service = args['name']
        state = args['state']

        if state == 'started':
            await conn.run(f"systemctl start {service}")
        elif state == 'stopped':
            await conn.run(f"systemctl stop {service}")
        elif state == 'restarted':
            await conn.run(f"systemctl restart {service}")
        elif state == 'enabled':
            await conn.run(f"systemctl enable {service}")

    async def manage_package(self, conn, args: Dict) -> Dict:
        """Manage packages"""
        package = args['name']
        state = args.get('state', 'present')

        # Check if package is installed
        check_result = await conn.run(f"dpkg -l | grep {package}", check=False)
        is_installed = check_result.exit_status == 0

        result = {'success': True, 'changed': False}

        if state == 'present' and not is_installed:
            await conn.run(f"apt-get update && apt-get install -y {package}")
            result['changed'] = True
        elif state == 'absent' and is_installed:
            await conn.run(f"apt-get remove -y {package}")
            result['changed'] = True

        return result

    def compile_results(self, results: List) -> Dict:
        """Compile execution results"""
        summary = {
            'total_hosts': len(results),
            'successful': 0,
            'failed': 0,
            'unreachable': 0,
            'results': []
        }

        for result in results:
            if isinstance(result, Exception):
                summary['failed'] += 1
                continue

            summary['results'].append(result)

            if result['status'] == 'success':
                summary['successful'] += 1
            elif result['status'] == 'failed':
                summary['failed'] += 1
            else:
                summary['unreachable'] += 1

        return summary

# Usage example
async def ansible_example():
    orchestrator = AnsibleLikeOrchestrator(max_concurrent=20)

    inventory = {
        'webservers': [
            {'hostname': '192.168.1.10', 'username': 'ubuntu'},
            {'hostname': '192.168.1.11', 'username': 'ubuntu'},
            {'hostname': '192.168.1.12', 'username': 'ubuntu'},
        ],
        'databases': [
            {'hostname': '192.168.1.20', 'username': 'ubuntu'},
            {'hostname': '192.168.1.21', 'username': 'ubuntu'},
        ]
    }

    playbook = [
        {
            'name': 'Update package cache',
            'module': 'command',
            'args': 'apt-get update'
        },
        {
            'name': 'Install nginx',
            'module': 'package',
            'args': {'name': 'nginx', 'state': 'present'}
        },
        {
            'name': 'Copy nginx config',
            'module': 'copy',
            'args': {'src': '/local/nginx.conf', 'dest': '/etc/nginx/nginx.conf'}
        },
        {
            'name': 'Start nginx service',
            'module': 'service',
            'args': {'name': 'nginx', 'state': 'started'}
        }
    ]

    results = await orchestrator.execute_playbook(inventory, playbook)
    print(f"Execution completed: {results}")
```

