import asyncio
import json
import time
from datetime import datetime, timedelta
from typing import Dict, List
import hashlib

class PuppetMaster:
    def __init__(self):
        self.agents = {}  # Connected agents
        self.catalogs = {}  # Compiled catalogs for each node
        self.reports = {}  # Agent reports
        self.environments = {}

    async def start_server(self, host='0.0.0.0', port=8140):
        """Start Puppet Master server"""
        server = await asyncio.start_server(
            self.handle_agent_connection, host, port
        )
        print(f"Puppet Master listening on {host}:{port}")
        async with server:
            await server.serve_forever()

    async def handle_agent_connection(self, reader, writer):
        """Handle connection from Puppet agent"""
        try:
            while True:
                data = await reader.read(4096)
                if not data:
                    break

                request = json.loads(data.decode())
                response = await self.process_agent_request(request)

                writer.write(json.dumps(response).encode())
                await writer.drain()

        except Exception as e:
            print(f"Error handling agent: {e}")
        finally:
            writer.close()
            await writer.wait_closed()

    async def process_agent_request(self, request: Dict) -> Dict:
        """Process request from Puppet agent"""
        agent_id = request['agent_id']
        request_type = request['type']

        if request_type == 'catalog_request':
            return await self.compile_catalog(agent_id, request['facts'])
        elif request_type == 'report':
            return await self.process_report(agent_id, request['report'])
        elif request_type == 'file_request':
            return await self.serve_file(request['file_path'])
        else:
            return {'error': 'Unknown request type'}

    async def compile_catalog(self, agent_id: str, facts: Dict) -> Dict:
        """Compile catalog for specific agent based on facts"""
        # Simulate catalog compilation based on node facts
        catalog = {
            'version': int(time.time()),
            'resources': [],
            'edges': [],
            'metadata': {
                'agent_id': agent_id,
                'compiled_at': datetime.now().isoformat(),
                'environment': facts.get('environment', 'production')
            }
        }

        # Add resources based on node classification
        if 'webserver' in facts.get('roles', []):
            catalog['resources'].extend([
                {
                    'type': 'package',
                    'title': 'nginx',
                    'parameters': {'ensure': 'present'}
                },
                {
                    'type': 'service',
                    'title': 'nginx',
                    'parameters': {'ensure': 'running', 'enable': True}
                },
                {
                    'type': 'file',
                    'title': '/etc/nginx/nginx.conf',
                    'parameters': {
                        'ensure': 'present',
                        'source': 'puppet:///modules/nginx/nginx.conf',
                        'checksum': 'md5'
                    }
                }
            ])

        if 'database' in facts.get('roles', []):
            catalog['resources'].extend([
                {
                    'type': 'package',
                    'title': 'postgresql',
                    'parameters': {'ensure': 'present'}
                },
                {
                    'type': 'service',
                    'title': 'postgresql',
                    'parameters': {'ensure': 'running', 'enable': True}
                }
            ])

        # Store compiled catalog
        self.catalogs[agent_id] = catalog

        return {'catalog': catalog}

    async def process_report(self, agent_id: str, report: Dict) -> Dict:
        """Process agent execution report"""
        self.reports[agent_id] = {
            'timestamp': datetime.now().isoformat(),
            'status': report['status'],
            'resources': report['resources'],
            'metrics': report.get('metrics', {}),
            'logs': report.get('logs', [])
        }

        # Analyze report for issues
        if report['status'] == 'failed':
            await self.handle_failed_run(agent_id, report)

        return {'status': 'received'}

    async def handle_failed_run(self, agent_id: str, report: Dict):
        """Handle failed Puppet runs"""
        print(f"Agent {agent_id} reported failed run:")
        for resource in report['resources']:
            if not resource.get('success', True):
                print(f"  Failed resource: {resource['type']}[{resource['title']}]")
                print(f"  Error: {resource.get('error', 'Unknown error')}")

class PuppetAgent:
    def __init__(self, agent_id: str, master_host='localhost', master_port=8140):
        self.agent_id = agent_id
        self.master_host = master_host
        self.master_port = master_port
        self.facts = {}
        self.last_catalog = None
        self.run_interval = 30  # seconds

    async def start_daemon(self):
        """Start Puppet agent daemon"""
        print(f"Starting Puppet agent {self.agent_id}")

        while True:
            try:
                await self.collect_facts()
                await self.request_catalog()
                await self.apply_catalog()
                await self.send_report()

            except Exception as e:
                print(f"Agent {self.agent_id} error: {e}")

            await asyncio.sleep(self.run_interval)

    async def collect_facts(self):
        """Collect system facts"""
        # Simulate fact collection
        self.facts = {
            'hostname': f"node-{self.agent_id}",
            'os': 'Ubuntu',
            'os_version': '20.04',
            'architecture': 'x86_64',
            'memory': '8GB',
            'roles': ['webserver'] if 'web' in self.agent_id else ['database'],
            'environment': 'production',
            'uptime': time.time()
        }

    async def request_catalog(self):
        """Request catalog from Puppet Master"""
        try:
            reader, writer = await asyncio.open_connection(
                self.master_host, self.master_port
            )

            request = {
                'type': 'catalog_request',
                'agent_id': self.agent_id,
                'facts': self.facts
            }

            writer.write(json.dumps(request).encode())
            await writer.drain()

            data = await reader.read(4096)
            response = json.loads(data.decode())

            if 'catalog' in response:
                self.last_catalog = response['catalog']
                print(f"Agent {self.agent_id} received catalog with {len(self.last_catalog['resources'])} resources")

            writer.close()
            await writer.wait_closed()

        except Exception as e:
            print(f"Failed to request catalog: {e}")

    async def apply_catalog(self):
        """Apply catalog resources"""
        if not self.last_catalog:
            return

        report = {
            'status': 'success',
            'resources': [],
            'metrics': {'total_time': 0, 'resources_applied': 0}
        }

        start_time = time.time()

        for resource in self.last_catalog['resources']:
            resource_result = await self.apply_resource(resource)
            report['resources'].append(resource_result)

            if not resource_result.get('success', True):
                report['status'] = 'failed'
            else:
                report['metrics']['resources_applied'] += 1

        report['metrics']['total_time'] = time.time() - start_time
        self.last_report = report

    async def apply_resource(self, resource: Dict) -> Dict:
        """Apply individual resource"""
        resource_result = {
            'type': resource['type'],
            'title': resource['title'],
            'success': True,
            'changed': False,
            'start_time': time.time()
        }

        try:
            if resource['type'] == 'package':
                # Simulate package management
                await asyncio.sleep(0.1)  # Simulate work
                resource_result['changed'] = True

            elif resource['type'] == 'service':
                # Simulate service management
                await asyncio.sleep(0.05)
                resource_result['changed'] = True

            elif resource['type'] == 'file':
                # Simulate file management
                await asyncio.sleep(0.02)
                resource_result['changed'] = True

        except Exception as e:
            resource_result['success'] = False
            resource_result['error'] = str(e)

        resource_result['end_time'] = time.time()
        resource_result['duration'] = resource_result['end_time'] - resource_result['start_time']

        return resource_result

    async def send_report(self):
        """Send execution report to master"""
        if not hasattr(self, 'last_report'):
            return

        try:
            reader, writer = await asyncio.open_connection(
                self.master_host, self.master_port
            )

            request = {
                'type': 'report',
                'agent_id': self.agent_id,
                'report': self.last_report
            }

            writer.write(json.dumps(request).encode())
            await writer.drain()

            writer.close()
            await writer.wait_closed()

        except Exception as e:
            print(f"Failed to send report: {e}")

# Orchestration and scaling utilities
class ConfigManagementOrchestrator:
    def __init__(self):
        self.batch_size = 50
        self.max_concurrent = 100

    async def rolling_deployment(self, hosts: List[str], playbook: List[Dict], 
                                batch_percentage: float = 0.2):
        """Perform rolling deployment across hosts"""
