                break

            print(f"Batch completed successfully")
            await asyncio.sleep(5)  # Brief pause between batches

    async def deploy_to_host(self, host: str, playbook: List[Dict]):
        """Deploy to individual host"""
        # Simulate deployment
        await asyncio.sleep(2)
        return f"Deployed to {host}"

