async def run_puppet_simulation():
    """Simulate Puppet master-agent architecture"""
    # Start master in background
    master = PuppetMaster()
    master_task = asyncio.create_task(master.start_server())

    # Wait for master to start
    await asyncio.sleep(1)

    # Start multiple agents
    agents = []
    for i in range(5):
        agent = PuppetAgent(f"web-{i}")
        agent_task = asyncio.create_task(agent.start_daemon())
