### 1. Connection Pooling and Multiplexing

```python
class SSHConnectionPool:
    def __init__(self, max_connections_per_host=5):
        self.pools = {}  # host -> connection pool
        self.max_connections = max_connections_per_host

    async def get_connection(self, host_config):
        host = host_config['hostname']

        if host not in self.pools:
            self.pools[host] = asyncio.Queue(maxsize=self.max_connections)

        pool = self.pools[host]

        try:
            # Try to get existing connection
            connection = pool.get_nowait()
            if await self.is_connection_alive(connection):
                return connection
        except asyncio.QueueEmpty:
            pass

        # Create new connection
        return await self.create_connection(host_config)

    async def return_connection(self, host, connection):
        """Return connection to pool"""
        if host in self.pools:
            try:
                self.pools[host].put_nowait(connection)
            except asyncio.QueueFull:
                # Pool is full, close connection
                await connection.close()
```

### 2. Batching and Rate Limiting

```python
class BatchExecutor:
    def __init__(self, batch_size=50, rate_limit=10):
        self.batch_size = batch_size
        self.rate_limiter = asyncio.Semaphore(rate_limit)

    async def execute_batched(self, hosts, tasks):
        """Execute tasks in batches with rate limiting"""
        for i in range(0, len(hosts), self.batch_size):
            batch = hosts[i:i + self.batch_size]

            async with self.rate_limiter:
                batch_tasks = [
                    self.execute_on_host(host, tasks) 
                    for host in batch
                ]
                await asyncio.gather(*batch_tasks)

            # Brief pause between batches
            await asyncio.sleep(0.1)
