    async def start_server(self, host='0.0.0.0', port=8140):
        """Start Puppet Master server"""
        server = await asyncio.start_server(
            self.handle_agent_connection, host, port
        )
        print(f"Puppet Master listening on {host}:{port}")
        async with server:
