    async def handle_agent_connection(self, reader, writer):
        """Handle connection from Puppet agent"""
        try:
            while True:
                data = await reader.read(4096)
                if not data:
                    break

                request = json.loads(data.decode())
                response = await self.process_agent_request(request)

                writer.write(json.dumps(response).encode())
                await writer.drain()

        except Exception as e:
            print(f"Error handling agent: {e}")
        finally:
            writer.close()
            await writer.wait_closed()

    async def process_agent_request(self, request: Dict) -> Dict:
        """Process request from Puppet agent"""
        agent_id = request['agent_id']
        request_type = request['type']

        if request_type == 'catalog_request':
            return await self.compile_catalog(agent_id, request['facts'])
        elif request_type == 'report':
            return await self.process_report(agent_id, request['report'])
        elif request_type == 'file_request':
            return await self.serve_file(request['file_path'])
        else:
